head.script:

scwin.onpageload = function() {
	var dataJson = [
		{"col1":"label1","col2":"value1"},
		{"col1":"label2","col2":"value2"},
		{"col1":"label3","col2":"value3"},
		{"col1":"label4","col2":"value4"},
		{"col1":"label5","col2":"value5"}
	]
	dataList1.setJSON(dataJson);

	checkbox1.setDisabled(true);
	checkbox1.setItemDisabled(0, false);
};

scwin.onpageunload = function() {

};


scwin.select1_oncheckboxclick = function(index,checked,value) {
	console.log("oncheckboxClick 클릭!!!");
	console.log(value);
	localStorage.setItem("log", value);		
};

scwin.checkVal = function() {
	return localStorage.getItem('log') == 'value1';
}	
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('checkbox1_input_0').click()");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
localStorage.removeItem("log");
